// Manual e2e for encryption-at-rest wiring (MRFC-0020 P0):
// serve (encrypted) -> remember -> verify plaintext absent from redb ->
// restart -> get returns plaintext -> wrong passphrase fails the open.
// Usage:
//   node scripts/e2e-enc-smoke.js <binary> <workdir>
// The workdir must contain aikoql.toml (encryption.enabled=true, policy on
// "employee") and a key file generated by `aikoql keygen`. Passphrase via
// AIKOQL_PASSPHRASE in the environment.
const { spawn, spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const [bin, workdir] = process.argv.slice(2);
const db = path.join(workdir, 'aikoql.redb');

// Watchdog: any phase taking longer than 90s total is a hang, not a test.
setTimeout(() => { console.error('e2e: watchdog timeout (90s) — aborting'); process.exit(1); }, 90000).unref();

function mcp(cmd, args) {
  // No shell:true — on Windows stdin piping through cmd.exe swallows frames.
  const child = spawn(cmd, args, { cwd: workdir, stdio: ['pipe', 'pipe', 'pipe'] });
  child.stderr.on('data', (c) => process.stderr.write('[serve] ' + c));
  child.on('error', (e) => { console.error('e2e: spawn failed:', e.message); process.exit(1); });
  let nextId = 0;
  const pending = new Map();
  let buffer = '';
  const req = (method, params) => new Promise((res, rej) => {
    const id = ++nextId;
    const timer = setTimeout(() => { pending.delete(id); rej(new Error(method + ' timed out (15s)')); }, 15000);
    pending.set(id, { res, rej, timer });
    child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n', (err) => {
      if (err) { clearTimeout(timer); pending.delete(id); rej(err); }
    });
  });
  child.stdout.on('data', (chunk) => {
    buffer += chunk.toString('utf8');
    let nl;
    while ((nl = buffer.indexOf('\n')) !== -1) {
      const line = buffer.slice(0, nl).trim();
      buffer = buffer.slice(nl + 1);
      if (!line) continue;
      let msg;
      try { msg = JSON.parse(line); } catch (_) { continue; }
      if (msg.id !== undefined && pending.has(msg.id)) {
        const { res, rej, timer } = pending.get(msg.id);
        pending.delete(msg.id);
        clearTimeout(timer);
        msg.error ? rej(new Error(JSON.stringify(msg.error))) : res(msg.result);
      }
    }
  });
  const run = async () => {
    const init = await req('initialize', { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'e2e-enc', version: '0' } });
    // Notification — the server never responds; fire and forget.
    child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized', params: {} }) + '\n');
    return {
      init,
      call: (name, arguments_) => req('tools/call', { name, arguments: arguments_ }),
      end: () => child.stdin.end(),
      kill: () => child.kill(),
      pid: child.pid,
    };
  };
  const exited = new Promise((res) => child.on('exit', (code) => {
    for (const { rej, timer } of pending.values()) { clearTimeout(timer); rej(new Error('serve exited (code ' + code + ') before response')); }
    pending.clear();
    res(code);
  }));
  return { run, exited };
}

(async () => {
  const pass = process.env.AIKOQL_PASSPHRASE;
  if (!pass) { console.error('AIKOQL_PASSPHRASE not set'); process.exit(2); }

  // Phase 1: serve + remember.
  const s1 = mcp(bin, ['serve', db]);
  const c1 = await s1.run();
  const rem = await c1.call('remember', {
    type_name: 'employee',
    properties: { name: 'Alice', salary: 150000, ssn: '123-45-6789' },
  });
  if (rem.isError) throw new Error('remember failed: ' + JSON.stringify(rem.content).slice(0, 200));
  const koid = JSON.parse(rem.content[0].text).koid;
  console.log('e2e: remembered', koid);

  const got1 = await c1.call('get', { koid });
  const obj1 = JSON.parse(got1.content[0].text);
  if (obj1.properties.salary !== 150000 || obj1.properties.ssn !== '123-45-6789') {
    throw new Error('get (same process) returned wrong values: ' + JSON.stringify(obj1.properties));
  }
  console.log('e2e: get (same process) OK — plaintext roundtrip');
  c1.end();
  await s1.exited; // serve flushes + closes the redb before we read bytes

  // Phase 2: plaintext must not be in the redb file.
  const raw = fs.readFileSync(db);
  const txt = raw.toString('latin1');
  for (const secret of ['123-45-6789', '150000']) {
    if (txt.includes(secret)) { console.error('e2e: LEAK — plaintext found in redb:', secret); process.exit(1); }
  }
  console.log('e2e: no plaintext in redb file — at-rest encryption verified');

  // Phase 3: restart serve, get again.
  const s2 = mcp(bin, ['serve', db]);
  const c2 = await s2.run();
  const got2 = await c2.call('get', { koid });
  const obj2 = JSON.parse(got2.content[0].text);
  if (obj2.properties.salary !== 150000 || obj2.properties.ssn !== '123-45-6789') {
    throw new Error('get (after restart) returned wrong values: ' + JSON.stringify(obj2.properties));
  }
  console.log('e2e: get (after restart) OK — DEKs persisted across restart');
  c2.end();
  await s2.exited;

  // Phase 4: wrong passphrase must fail the open (fail-closed).
  const wrong = spawnSync(bin, ['serve', db], {
    cwd: workdir,
    env: { ...process.env, AIKOQL_PASSPHRASE: 'wrong-passphrase' },
    timeout: 30000,
  });
  if (wrong.status === 0 || wrong.status === null) {
    console.error('e2e: wrong passphrase did NOT fail the open (exit', wrong.status, ')');
    process.exit(1);
  }
  console.log('e2e: wrong passphrase fails the open (exit', wrong.status, ') — fail-closed verified');
  process.exit(0);
})().catch((e) => { console.error('E2E FAILED:', e.message); process.exit(1); });
